{
    public function __construct(
        private EntityManagerInterface $em,
        private \Twilio\Rest\Client $twilio,
    ) {
    }

    public function __invoke(ConfirmOrder $command): void
    {
        $order = $this->em->find(Order::class, $command->orderId);
        $order->confirm();
        $this->em->flush();
        $this->twilio->messages->create($order->phone(), ['body' => 'Confirmed']);
    }
}

